def invert_tree(root):
    def nodes_at_depth(node, depth, target, found):
        if node is None:
            return
        if depth == target:
            found.append(node)
            return
        nodes_at_depth(node.left, depth + 1, target, found)
        nodes_at_depth(node.right, depth + 1, target, found)
    level = 0
    while True:
        found = []
        nodes_at_depth(root, 0, level, found)
        if not found:
            break
        for node in found:
            node.left, node.right = node.right, node.left
        level += 1
    return root
